type Memo struct {
	ID         int32
	UID        string
	RowStatus  RowStatus
	CreatorID  int32
	CreatedTs  int64
	UpdatedTs  int64
	Content    string
	Visibility Visibility
	Pinned     bool
	Payload    *storepb.MemoPayload
